import app from 'flarum/admin/app';
/**
 * A single labeled stat tile. `labelKey` is the full translator key so every
 * label greps to its use site; `sub` carries context such as a percentage.
 */
export function statTile(key, labelKey, value, sub, href) {
  const content = [m("div", {
    className: "RedisWidget-tileLabel"
  }, app.translator.trans(labelKey)), m("div", {
    className: "RedisWidget-tileValue"
  }, value ?? '0'), sub && m("div", {
    className: "RedisWidget-tileSub"
  }, sub)];
  const className = `RedisWidget-tile RedisWidget-tile--${key}`;
  return href ? m("a", {
    className: className,
    href: href,
    target: "_blank",
    rel: "noopener noreferrer"
  }, content) : m("div", {
    className: className
  }, content);
}